  1	package jobs
  2	
  3	import "time"
  4	
  5	func (j *Service) Expire(now time.Time) error {
  6	
  7		tx, e := j.S.DB.Begin()
  8		if e != nil {
  9			return e
 10		}
 11		defer tx.Rollback()
 12		rows, e := tx.Query(`SELECT id,attempts+1,max_attempts,leased_by FROM jobs WHERE state='leased' AND lease_expires_at <= $1 FOR UPDATE SKIP LOCKED`, now)
 13		if e != nil {
 14			return e
 15		}
 16		type expired struct {
 17			id, worker int64
 18			n, max     int
 19		}
 20		batch := []expired{}
 21		for rows.Next() {
 22			var r expired
 23			if e = rows.Scan(&r.id, &r.n, &r.max, &r.worker); e != nil {
 24				rows.Close()
 25				return e
 26			}
 27			batch = append(batch, r)
 28		}
 29		e = rows.Err()
 30		rows.Close()
 31		if e != nil {
 32			return e
 33		}
 34		dead := []int64{}
 35		for _, r := range batch {
 36			state := "queued"
 37			if r.n >= r.max {
 38				state = "dead"
 39				dead = append(dead, r.id)
 40			}
 41			_, e = tx.Exec(`UPDATE jobs SET state=$2,attempts=$3,last_error='lease expired',lease_token=NULL,leased_by=NULL,lease_expires_at=NULL,finished_at=CASE WHEN $2='dead' THEN $4::timestamptz ELSE NULL END WHERE id=$1`, r.id, state, r.n, now)
 42			if e != nil {
 43				return e
 44			}
 45			_, e = tx.Exec(`INSERT INTO attempts VALUES($1,$2,$3,$4,$4,'expired','lease expired')`, r.id, r.n, r.worker, now)
 46			if e != nil {
 47				return e
 48			}
 49		}
 50		if e = tx.Commit(); e != nil {
 51			return e
 52		}
 53		for _, id := range dead {
 54			if e = j.Notify(id, now); e != nil {
 55				return e
 56			}
 57		}
 58		return nil
 59	}
 60	
 61	func (j *Service) Promote(now time.Time) error {
 62		_, e := j.S.DB.Exec(`UPDATE jobs SET state='queued' WHERE state IN ('scheduled','retry_wait') AND run_at <= $1`, now)
 63		return e
 64	}
 65	func (j *Service) Retain(now time.Time) error {
 66		_, e := j.S.DB.Exec(`DELETE FROM jobs j USING queues q WHERE j.queue_id=q.id AND j.state IN ('succeeded','cancelled','dead') AND j.finished_at < $1::timestamptz - q.retention_hours * interval '1 hour'`, now)
 67		return e
 68	}
 69	package webhook
 70	
 71	import (
 72		"bytes"
 73		"crypto/hmac"
 74		"crypto/sha256"
 75		"encoding/hex"
 76		"encoding/json"
 77		"io"
 78		"log"
 79		"net/http"
 80		"queuelet/internal/store"
 81		"time"
 82	)
 83	
 84	func Ship(s *store.Store, now time.Time) error {
 85		rows, e := s.Rows(`SELECT * FROM webhook_outbox WHERE delivered_at IS NULL AND next_at <= $1 ORDER BY id LIMIT 20`, now)
 86		if e != nil {
 87			return e
 88		}
 89		for _, r := range rows {
 90			body, _ := json.Marshal(r["body"])
 91			mac := hmac.New(sha256.New, []byte(r["secret"].(string)))
 92			mac.Write(body)
 93			req, e := http.NewRequest("POST", r["url"].(string), bytes.NewReader(body))
 94			if e != nil {
 95				return e
 96			}
 97			req.Header.Set("Content-Type", "application/json")
 98			req.Header.Set("X-Queuelet-Signature", hex.EncodeToString(mac.Sum(nil)))
 99			resp, e := (&http.Client{Timeout: 2 * time.Second}).Do(req)
100			if e != nil || resp.StatusCode < 200 || resp.StatusCode >= 300 {
101				if resp != nil {
102					io.Copy(io.Discard, resp.Body)
103					resp.Body.Close()
104				}
105				_, e = s.DB.Exec(`UPDATE webhook_outbox SET attempts=attempts+1,next_at=$2 WHERE id=$1`, r["id"], now.Add(5*time.Second))
106				if e != nil {
107					return e
108				}
109				continue
110			}
111			io.Copy(io.Discard, resp.Body)
112			resp.Body.Close()
113			log.Printf("webhook delivered status=%d", resp.StatusCode)
114			_, e = s.DB.Exec(`UPDATE webhook_outbox SET delivered_at=$2,attempts=attempts+1 WHERE id=$1`, r["id"], now)
115			if e != nil {
116				return e
117			}
118		}
119		return nil
120	}
 90		m.HandleFunc("DELETE /v1/schedules/{id}", s.deleteSchedule)
 91		m.HandleFunc("POST /v1/schedules/{id}/run", s.runSchedule)
 92		m.HandleFunc("GET /v1/namespaces/{ns}/stats", s.namespaceStats)
 93		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
 94			if r.URL.Path == "/health" || r.URL.Path == "/metrics" {
 95				m.ServeHTTP(w, r)
 96				return
 97			}
 98			h := sha256.Sum256([]byte(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")))
 99			var id identity
100			if e := s.S.DB.QueryRow(`SELECT namespace_id,admin FROM api_keys WHERE key_hash=$1`, hex.EncodeToString(h[:])).Scan(&id.Namespace, &id.Admin); e != nil {
101				if e == sql.ErrNoRows {
102					fail(w, 401, "unauthorized", "invalid API key")
103				} else {
104					fail(w, 503, "auth_unavailable", "authentication store unavailable")
105				}
106				return
107			}
108			m.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), authKey{}, id)))
109		})
110	}
111	func (s *Server) Loop(ctx context.Context) {
112		// A single shipper preserves delivery ordering without blocking lifecycle sweeps.
113		go func() {
114			t := time.NewTicker(time.Second)
115			defer t.Stop()
116			for {
117				select {
118				case <-ctx.Done():
119					return
120				case now := <-t.C:
121					e := webhook.Ship(s.S, now)
122					s.shipFailed.Store(e != nil)
123					if e != nil {
124						log.Printf("webhook task: %v", e)
125					}
126				}
127			}
128		}()
129		t := time.NewTicker(time.Second)
130		defer t.Stop()
131		for {
132			select {
133			case <-ctx.Done():
134				return
135			case now := <-t.C:
136				failed := false
137				for _, step := range []func(time.Time) error{s.Jobs.Promote, s.Jobs.Expire, func(t time.Time) error { return schedule.Fire(s.S, t) }, s.Jobs.Retain} {
138					if e := step(now); e != nil {
139						log.Printf("background task: %v", e)
140						failed = true
141					}
142				}
143				s.coreFailed.Store(failed)
144			}
145		}
146	}
147	func (s *Server) queue(r *http.Request) (map[string]any, error) {
148		name := r.PathValue("q")
149		if strings.ContainsAny(name, "/ ") {
150			return nil, fmt.Errorf("invalid queue path")
151		}
152		return s.S.One(`SELECT * FROM queues WHERE namespace_id=$1 AND name=$2`, ident(r).Namespace, name)
153	}
154	func (s *Server) queueOrError(w http.ResponseWriter, r *http.Request) (map[string]any, bool) {
155		q, e := s.queue(r)
156		if e != nil {
157			fail(w, 404, "queue_not_found", e)
158			return nil, false
159		}
160		return q, true
161	}
162	func output(w http.ResponseWriter, v any, e error) {
163		if e != nil {
164			fail(w, 500, "database_error", e)
165			return
166		}
167		write(w, 200, v)
168	}

