  1	package worker
  2	
  3	import (
  4		"context"
  5		"encoding/json"
  6		"fmt"
  7		"io"
  8		"log"
  9		"net/http"
 10		"os"
 11		"queuelet/internal/client"
 12		"strconv"
 13		"strings"
 14		"time"
 15	)
 16	
 17	type Job struct {
 18		ID      int64          `json:"id"`
 19		Kind    string         `json:"kind"`
 20		Payload map[string]any `json:"payload"`
 21		Attempt int            `json:"attempt"`
 22		Token   string         `json:"lease_token"`
 23	}
 24	
 25	func Run(ctx context.Context, c *client.Client, name, queue string, kinds []string) error {
 26		var reg struct {
 27			ID int64 `json:"worker_id"`
 28		}
 29		if e := c.JSON("POST", "/v1/workers", map[string]any{"name": name, "kinds": kinds}, &reg); e != nil {
 30			return e
 31		}
 32		log.Printf("worker %s registered", name)
 33		for {
 34			select {
 35			case <-ctx.Done():
 36				return nil
 37			default:
 38			}
 39			var batch struct {
 40				Jobs []Job `json:"jobs"`
 41			}
 42			if e := c.JSON("POST", "/v1/queues/"+queue+"/lease", map[string]any{"worker_id": reg.ID, "max_jobs": 1}, &batch); e != nil {
 43				log.Print(e)
 44				time.Sleep(time.Second)
 45				continue
 46			}
 47			for _, j := range batch.Jobs {
 48				log.Printf("processing kind=%s attempt=%d", j.Kind, j.Attempt)
 49				done := make(chan struct{})
 50				go func(j Job) {
 51					t := time.NewTicker(5 * time.Second)
 52					defer t.Stop()
 53					for {
 54						select {
 55						case <-done:
 56							return
 57						case <-t.C:
 58							c.Do("POST", fmt.Sprintf("/v1/jobs/%d/heartbeat", j.ID), map[string]any{"lease_token": j.Token, "extend_seconds": 30})
 59						}
 60					}
 61				}(j)
 62				result, e := perform(j)
 63				close(done)
 64				verb := "ack"
 65				body := map[string]any{"lease_token": j.Token, "result": result}
 66				if e != nil {
 67					verb = "nack"
 68					body = map[string]any{"lease_token": j.Token, "error": e.Error(), "retry": true}
 69				}
 70				_, status, e := c.Do("POST", fmt.Sprintf("/v1/jobs/%d/%s", j.ID, verb), body)
 71				log.Printf("completed status=%d error=%v", status, e)
 72			}
 73			time.Sleep(200 * time.Millisecond)
 74		}
 75	}
 76	func perform(j Job) (any, error) {
 77		switch {
 78		case j.Kind == "echo":
 79			return j.Payload, nil
 80		case j.Kind == "sleep":
 81			seconds, _ := j.Payload["seconds"].(float64)
 82			time.Sleep(time.Duration(seconds * float64(time.Second)))
 83			return j.Payload, nil
 84		case j.Kind == "crash":
 85			os.Exit(3)
 86		case strings.HasPrefix(j.Kind, "fail"):
 87			n, _ := j.Payload["n"].(float64)
 88			if n == 0 {
 89				v, _ := strconv.Atoi(strings.TrimPrefix(j.Kind, "fail"))
 90				n = float64(v)
 91			}
 92			if j.Attempt <= int(n) {
 93				return nil, fmt.Errorf("requested failure %d", j.Attempt)
 94			}
 95			return j.Payload, nil
 96		case j.Kind == "http":
 97			url, _ := j.Payload["url"].(string)
 98			resp, e := (&http.Client{Timeout: 5 * time.Second}).Get(url)
 99			if e != nil {
100				return nil, e
101			}
102			defer resp.Body.Close()
103			b, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
104			if resp.StatusCode >= 400 {
105				return nil, fmt.Errorf("remote status %d", resp.StatusCode)
106			}
107			var v any
108			if json.Unmarshal(b, &v) != nil {
109				v = string(b)
110			}
111			return v, nil
112		}
113		return nil, fmt.Errorf("unknown kind %s", j.Kind)
114	}
115	package main
116	
117	import (
118		"context"
119		"log"
120		"os"
121		"os/signal"
122		"queuelet/internal/client"
123		"queuelet/internal/worker"
124		"strings"
125		"syscall"
126	)
127	
128	func main() {
129		ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
130		defer stop()
131		name := os.Getenv("WORKER_NAME")
132		q := os.Getenv("WORKER_QUEUE")
133		if q == "" {
134			q = "emails"
135		}
136		kinds := os.Getenv("WORKER_KINDS")
137		if kinds == "" {
138			kinds = "echo,sleep,fail,crash,http"
139		}
140		if e := worker.Run(ctx, client.Env(), name, q, strings.Split(kinds, ",")); e != nil {
141			log.Fatal(e)
142		}
143	}
144	package jobs
145	
146	import "time"
147	
148	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
149		tx, e := j.S.DB.Begin()
150		if e != nil {
151			return e
152		}
153		defer tx.Rollback()
154		var attempts, max, base int
155		var kind string
156		var worker int64
157		e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,j.leased_by FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 FOR UPDATE OF j`, id, token).Scan(&attempts, &max, &kind, &base, &worker)
158		if e != nil {
159			return e
160		}
161		state := "retry_wait"
162		if !retry || attempts >= max {
163			state = "dead"
164		}
165		wait := Backoff(kind, base, attempts)
166		if delay != nil {
167			wait = time.Duration(*delay) * time.Second
168		}
169		_, e = tx.Exec(`UPDATE jobs SET state=$2,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
170		if e != nil {
171			return e
172		}
173		_, e = tx.Exec(`INSERT INTO attempts VALUES($1,$2,$3,$4,$4,'failed',$5)`, id, attempts, worker, now, message)
174		if e != nil {
175			return e
176		}
177		if e = tx.Commit(); e != nil {
178			return e
179		}
180		if state == "dead" {
181			return j.Notify(id, now)
182		}
183		return nil
184	}
185	package jobs
186	
187	import (
188		"encoding/json"
189		"time"
190	)
191	
192	func (j *Service) Ack(id int64, token string, result any, now time.Time) error {
193		b, _ := json.Marshal(result)
194		r, e := j.S.DB.Exec(`UPDATE jobs SET state='succeeded',result=$2,finished_at=$3,attempts=attempts+1 WHERE id=$1 AND state='leased' AND lease_token=$4`, id, string(b), now, token)
195		if e = Changed(r, e); e != nil {
196			return e
197		}
