145	
146	import "time"
147	
148	func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
149		tx, e := j.S.DB.Begin()
150		if e != nil {
151			return e
152		}
153		defer tx.Rollback()
154		var attempts, max, base int
155		var kind string
156		var worker int64
157		e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,j.leased_by FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 FOR UPDATE OF j`, id, token).Scan(&attempts, &max, &kind, &base, &worker)
158		if e != nil {
159			return e
160		}
161		state := "retry_wait"
162		if !retry || attempts >= max {
163			state = "dead"
164		}
165		wait := Backoff(kind, base, attempts)
166		if delay != nil {
167			wait = time.Duration(*delay) * time.Second
168		}
169		_, e = tx.Exec(`UPDATE jobs SET state=$2,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
170		if e != nil {
171			return e
172		}
173		_, e = tx.Exec(`INSERT INTO attempts VALUES($1,$2,$3,$4,$4,'failed',$5)`, id, attempts, worker, now, message)
174		if e != nil {
175			return e
176		}
177		if e = tx.Commit(); e != nil {
178			return e
179		}
180		if state == "dead" {
181			return j.Notify(id, now)
182		}
183		return nil
184	}
